package com.lolzcloud.mobile;

import org.json.*;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.security.MessageDigest;import java.util.*;

/** Explicit anonymous public metadata probe. Emits hashes/counts/times, never source words. */
public final class LyricsTempoLiveProbe {
    public static void main(String[] args)throws Exception{
        if(args.length!=1)throw new IllegalArgumentException("One D-only report path required");
        JSONArray cases=new JSONArray();Map<String,JSONArray> records=new HashMap<>();int[] writes={0};LyricsProvider.Cache cache=new LyricsProvider.Cache(){public JSONArray read(LyricsMetadata.Query query){return records.get(query.canonicalKey());}public void write(LyricsMetadata.Query query,JSONArray rows){writes[0]++;records.put(query.canonicalKey(),rows);}};
        LyricsProvider provider=new LyricsProvider("0.1.10");boolean success=true;
        String[][] tracks={{"2006992171","тёмный принц - отвратительный король (speed up)","ㅤ","93000"},{"2097182523","Темный принц - отвратительный король (speed up)","SNXXX","86000"},{"2215259861","тёмный принц - отвратительный король (slowed & reverb)","Prince Flowers","139000"}};
        for(String[] track:tracks){long source=Long.parseLong(track[3]),started=System.nanoTime();LyricsProvider.Result result=provider.lookup(LyricsMetadata.candidates(track[1],track[2],source),cache,false);List<LrcParser.Line> lines=LrcParser.parse(result.text);boolean passed=result.timed&&result.adapted&&result.referenceDuration==111000&&result.duration==source&&Math.abs(result.adaptationRate-111000d/source)<.000001&&result.referenceEvidence.equals("catalog-consensus");success&=passed;cases.put(new JSONObject().put("sourceId",track[0]).put("rawTitle",track[1]).put("uploader",track[2]).put("sourceDurationMs",source).put("referenceDurationMs",result.referenceDuration).put("referenceEvidence",result.referenceEvidence).put("recordId",result.recordId).put("matchedTitle",result.title).put("matchedArtist",result.artist).put("found",result.found()).put("timed",result.timed).put("adapted",result.adapted).put("rate",result.adaptationRate).put("lines",lines.size()).put("firstTimeMs",lines.isEmpty()?-1:lines.get(0).time).put("lastTimeMs",lines.isEmpty()?-1:lines.get(lines.size()-1).time).put("adaptedTextSha256",hex(MessageDigest.getInstance("SHA-256").digest(result.text.getBytes(StandardCharsets.UTF_8)))).put("elapsedMs",(System.nanoTime()-started)/1000000).put("passed",passed));}
        success&=writes[0]==1;JSONObject report=new JSONObject().put("status",success?"passed":"no_verified_tempo_match").put("checkedAt",java.time.Instant.now().toString()).put("realPublicHttps",true).put("source","https://lrclib.net").put("canonicalResponseCacheWrites",writes[0]).put("sourceTextPrinted",false).put("cases",cases).put("scope","Production frozen Java metadata/provider/LRC policy on the host JVM; one live anonymous canonical LRCLIB response reused across3 already corroborated SoundCloud source durations. No audio download, personal account, Android UI or physical acoustic claim.");Files.write(Paths.get(args[0]),(report.toString(2)+"\n").getBytes(StandardCharsets.UTF_8));System.out.println("Live tempo probe "+report.getString("status")+": "+cases.length()+" variants, "+writes[0]+" canonical cache writes; source words omitted");if(!success)throw new AssertionError("Public source did not provide verified expected variants");
    }
    private static String hex(byte[] bytes){StringBuilder out=new StringBuilder();for(byte value:bytes)out.append(String.format(Locale.ROOT,"%02x",value&255));return out.toString();}
}
